// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract TimestampLottery {function win() external view returns(bool){return block.timestamp%17==0;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract DeadlineWindow {function execute(uint deadline) external view {require(block.timestamp<=deadline);}}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SignatureReplay {address public signer;constructor(address s){signer=s;}function run(bytes32 h,uint8 v,bytes32 r,bytes32 s) external view {require(ecrecover(h,v,r,s)==signer);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SignatureDomain {address public signer;mapping(bytes32=>bool) public used;constructor(address s){signer=s;}function run(bytes32 action,uint nonce,uint8 v,bytes32 r,bytes32 s) external {bytes32 h=keccak256(abi.encode(block.chainid,address(this),action,nonce));require(!used[h]);require(ecrecover(h,v,r,s)==signer);used[h]=true;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PermitNoDeadline {mapping(address=>uint) public nonces;function permit(address owner,address spender,uint amount,uint8 v,bytes32 r,bytes32 s) external {bytes32 h=keccak256(abi.encode(owner,spender,amount,nonces[owner]++));require(ecrecover(h,v,r,s)==owner);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PermitDeadline {mapping(address=>uint) public nonces;function permit(address owner,address spender,uint amount,uint deadline,uint8 v,bytes32 r,bytes32 s) external {require(block.timestamp<=deadline);bytes32 h=keccak256(abi.encode(block.chainid,address(this),owner,spender,amount,deadline,nonces[owner]++));require(ecrecover(h,v,r,s)==owner);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract ImplV1 {address public owner;uint public value;} contract ImplV2 {uint public value;address public owner;}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

library Slot {bytes32 constant POS=keccak256("velmere.storage.v1");struct Data{address owner;uint value;}function data() internal pure returns(Data storage d){bytes32 p=POS;assembly{d.slot:=p}}} contract Namespaced {function owner() external view returns(address){return Slot.data().owner;}}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Destructible {address public owner;constructor(){owner=msg.sender;}function destroy(address payable to) external {require(msg.sender==owner);selfdestruct(to);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract ImmutableVault {address public immutable owner;constructor(){owner=msg.sender;}receive() external payable{} }
